<?php
namespace App\Filament\Pages;
use App\Services\AgendaFlowEditor;
use Illuminate\Support\Facades\DB;
use Livewire\Attributes\Locked;
use Filament\Notifications\Notification;
class AgendaFluxos extends \Filament\Pages\Page {
    // Registrada pelo AgendaPanelProvider na edicao Agenda; fora do painel do chat.
    protected static bool $isDiscovered = false;

 protected static ?string $slug='fluxos';protected static ?string $title='Fluxos';protected static string|\UnitEnum|null $navigationGroup='Automações';protected static string|\BackedEnum|null $navigationIcon='heroicon-o-rectangle-group';protected string $view='filament.pages.agenda-fluxos';
 #[Locked] public int $flowId=0;#[Locked] public int $version=0;#[Locked] public array $simState=[];#[Locked] public array $transcript=[];
 public string $name='';public array $graph=[];public string $selected='';public string $channel='';public string $input='';public string $newType='message';public bool $newCustomer=false;
 public static function canAccess():bool{return AgendaFluxoWhatsApp::canAccess();}
 private function editor():AgendaFlowEditor {$e=app(AgendaFlowEditor::class);$e->guard(auth()->user());return $e;}
 public function rows(){ $this->editor();return DB::table('agenda_editor_flows')->where('tenant_id',auth()->user()->tenant_id)->whereNull('archived_at')->orderByDesc('updated_at')->get();}
 public function delete(int $id):void {$this->editor()->delete(auth()->user(),$id);if($this->flowId===$id)$this->flowId=0;Notification::make()->success()->title('Fluxo excluído')->send();}
 public function channels(){ $this->editor();return \App\Models\Channel::withoutGlobalScopes()->where('tenant_id',auth()->user()->tenant_id)->where('tipo','evolution')->orderBy('nome')->get();}
 public function bindings(){ $this->editor();return DB::table('agenda_flow_settings as s')->join('agenda_editor_revisions as r','r.id','=','s.editor_revision_id')->where('s.tenant_id',auth()->user()->tenant_id)->select('s.channel_id','s.enabled','r.flow_id','r.version')->get();}
 public function open(int $id):void {$f=$this->editor()->find(auth()->user(),$id);$this->flowId=$id;$this->version=$f->version;$this->name=$f->name;$this->graph=json_decode($f->draft,true);$this->selected=$this->graph[0]['id'];$this->channel='';$this->resetSimulation();}
 public function back():void {$this->editor();$this->flowId=0;}
 public function create(bool $model=true):void {$this->open($this->editor()->create(auth()->user(),'Novo fluxo',$model));}
 public function createBarbershop():void {$e=$this->editor();$id=$e->create(auth()->user(),'Agendamento da barbearia',false);$e->save(auth()->user(),$id,1,'Agendamento da barbearia',$e::barbershop());$this->open($id);$this->organizar();$this->save();}
 public function duplicate(int $id):void {$e=$this->editor();$f=$e->find(auth()->user(),$id);$new=$e->create(auth()->user(),mb_substr($f->name.' — cópia',0,120));$e->save(auth()->user(),$new,1,mb_substr($f->name.' — cópia',0,120),json_decode($f->draft,true));$this->open($new);}
 public function save():void {$this->version=$this->editor()->save(auth()->user(),$this->flowId,$this->version,$this->name,$this->graph);Notification::make()->success()->title('Rascunho salvo')->send();}
 public function add():void {$this->editor();abort_unless(isset(AgendaFlowEditor::TYPES[$this->newType])&&$this->newType!=='identify',422);$id='bloco_'.bin2hex(random_bytes(4));$node=['id'=>$id,'type'=>$this->newType,'title'=>AgendaFlowEditor::TYPES[$this->newType],'text'=>'','next'=>''];if($this->newType==='menu')$node['options']=[['label'=>'Primeira opção','to'=>''],['label'=>'Segunda opção','to'=>'']];if($this->newType==='condition')$node+=['equals'=>'sim','yes'=>'','no'=>''];$this->graph[]=$node;$this->selected=$id;}
 public function remove(string $id):void {$this->editor();abort_if($id===($this->graph[0]['id']??null),422);$this->graph=array_values(array_filter($this->graph,fn($n)=>$n['id']!==$id));$this->selected=$this->graph[0]['id'];}
 public function select(string $id):void {$this->editor();abort_unless(in_array($id,array_column($this->graph,'id')),404);$this->selected=$id;}
 public function desenho():array {$this->editor();$out=[];$layout=$this->layout();foreach($this->graph as $n){$handles=[];$edges=[];if($n['type']==='menu'){foreach($n['options'] as $k=>$o){$h='option_'.$k;$handles[]=['handle'=>$h,'rotulo'=>$o['label']];$edges[$h]=$o['to'];}}elseif($n['type']==='condition'){foreach(['yes'=>'Se igual','no'=>'Se diferente'] as $h=>$label){$handles[]=['handle'=>$h,'rotulo'=>$label];$edges[$h]=$n[$h];}}elseif(!in_array($n['type'],['end','human'])){$handles[]=['handle'=>'next','rotulo'=>'Continuar'];$edges['next']=$n['next']??'';}$out[]=$n+['x'=>$layout[$n['id']][0],'y'=>$layout[$n['id']][1],'handles'=>$handles,'saidas'=>$edges];}return $out;}
 private function layout():array {$depth=[];$queue=[[$this->graph[0]['id']??'',0]];$map=array_column($this->graph,null,'id');while($queue){[$id,$d]=array_shift($queue);if(isset($depth[$id])||!isset($map[$id]))continue;$depth[$id]=$d;$n=$map[$id];$edges=match($n['type']){'menu'=>array_column($n['options'],'to'),'condition'=>[$n['yes'],$n['no']],'end','human'=>[],default=>[$n['next']??'']};foreach($edges as $to)$queue[]=[$to,$d+1];}$rows=[];$positions=[];foreach($this->graph as $i=>$n){$col=$n['type']==='end'?(max($depth?:[0])+1):($depth[$n['id']]??($i%4));$row=$rows[$col]??0;$positions[$n['id']]=[$col*340,$row*270];$rows[$col]=$row+1;}return $positions;}
 public function organizar():void {$this->editor();$layout=$this->layout();foreach($this->graph as &$n){[$n['x'],$n['y']]=$layout[$n['id']];}}
 public function moverPasso(string $id,int $x,int $y):void {$this->editor();abort_unless($x>=0&&$x<=6000&&$y>=0&&$y<=4000,422);foreach($this->graph as &$n)if($n['id']===$id){$n['x']=$x;$n['y']=$y;return;}abort(404);}
 public function addAt(int $x,int $y):void {$this->add();$this->moverPasso($this->selected,min(6000,$x),min(4000,$y));}
 public function ligar(string $from,string $handle,string $to):void {$this->editor();abort_unless($from!==$to&&in_array($to,array_column($this->graph,'id')),422);foreach($this->graph as &$n)if($n['id']===$from){if($n['type']==='menu'&&preg_match('/^option_(\d+)$/',$handle,$m)&&isset($n['options'][(int)$m[1]])){$n['options'][(int)$m[1]]['to']=$to;return;}if($n['type']==='condition'&&in_array($handle,['yes','no'])){$n[$handle]=$to;return;}if(!in_array($n['type'],['menu','condition','end','human'])&&$handle==='next'){$n['next']=$to;return;}abort(422);}abort(404);}
 public function desligar(string $from,string $handle):void {$this->editor();foreach($this->graph as &$n)if($n['id']===$from){if($n['type']==='menu'&&preg_match('/^option_(\d+)$/',$handle,$m)&&isset($n['options'][(int)$m[1]])){$n['options'][(int)$m[1]]['to']='';return;}if($n['type']==='condition'&&in_array($handle,['yes','no'])){$n[$handle]='';return;}if(!in_array($n['type'],['menu','condition','end','human'])&&$handle==='next'){$n['next']='';return;}abort(422);}abort(404);}
 public function option():void {$this->editor();foreach($this->graph as &$n)if($n['id']===$this->selected&&$n['type']==='menu'&&count($n['options'])<10)$n['options'][]=['label'=>'Nova opção','to'=>''];}
 public function removeOption(int $index):void {$this->editor();foreach($this->graph as &$n)if($n['id']===$this->selected&&$n['type']==='menu'){unset($n['options'][$index]);$n['options']=array_values($n['options']);}}
 public function publish():void {$this->save();$this->editor()->publish(auth()->user(),$this->flowId,$this->version,(int)$this->channel);Notification::make()->success()->title('Fluxo publicado no canal selecionado')->send();}
 public function pause(int $channel):void {$this->editor();DB::table('agenda_flow_settings')->where('tenant_id',auth()->user()->tenant_id)->where('channel_id',$channel)->update(['enabled'=>false,'updated_at'=>now()]);Notification::make()->success()->title('Automação pausada')->send();}
 public function revisions(){ $this->editor();return DB::table('agenda_editor_revisions')->where('tenant_id',auth()->user()->tenant_id)->where('flow_id',$this->flowId)->orderByDesc('version')->get();}
 public function restore(int $id):void {$this->editor()->find(auth()->user(),$this->flowId);$r=DB::table('agenda_editor_revisions')->where('tenant_id',auth()->user()->tenant_id)->where('flow_id',$this->flowId)->where('id',$id)->firstOrFail();$this->graph=json_decode($r->graph,true);$this->selected=$this->graph[0]['id'];$this->resetSimulation();Notification::make()->success()->title('Versão restaurada no rascunho. Salve ou publique para aplicar.')->send();}
 public function resetSimulation():void {$this->editor();$this->simState=$this->newCustomer?[]:['name'=>'Marina (teste)'];$this->transcript=[];$this->input='';}
 public function simulateAppointment():void {$this->editor();$this->newCustomer=false;$this->resetSimulation();foreach(['olá','2'] as $input){$this->input=$input;$this->simulate();}}
 public function simulate():void {$e=$this->editor();$this->validate(['input'=>'required|string|max:200']);$errors=$e->problems($this->graph);if($errors)throw \Illuminate\Validation\ValidationException::withMessages(['graph'=>implode(' ',$errors)]);$cfg=(object)['editor_revision_id'=>null,'business_name'=>\App\Models\Tenant::find(auth()->user()->tenant_id)->nome,'address'=>'','greeting'=>'','handoff'=>'A equipe assumiria o atendimento.'];if(($this->simState['_human']??false))$text='Atendimento humano. Reinicie para testar outro caminho.';else{[$step,$this->simState,$text]=$e->advance(auth()->user(),$cfg,0,$this->simState,$this->input,true,$this->graph);if($step==='human')$this->simState['_human']=true;}$this->transcript=array_slice([...$this->transcript,['client'=>$this->input,'bot'=>$text]],-20);$this->input='';}
}
